				"野外战斗、抓鬼、封妖、官职、种族等活动任务中所获得的经验、银子、储备翻倍。本效果可以与双倍时间叠加。"
			}
		elseif 任务数据[任务id].类型 == 4 then
			local NPC = 取NPC寻路信息(任务数据[任务id].地图编号, 任务数据[任务id].名称, 任务数据[任务id].x, 任务数据[任务id].y)
