				"宝图任务",
				format("前往#Y/%s(%s,%s)#W/#S/处缉拿强盗#R/%s", 取地图名称(任务数据[任务id].地图编号), 任务数据[任务id].x, 任务数据[任务id].y, NPC),
				"完成后可获得少量金钱、几率获得藏宝图"
