			if 任务数据[任务id].分类 == 1 then
				说明 = {
					"雪人任务",
					format("替雪人给#R/%s#的#R%s#送上祝福。", 取地图名称(任务数据[任务id].地图编号), 任务数据[任务id].人物)
				}
			elseif 任务数据[任务id].分类 == 2 then
				说明 = {
					"雪人任务",
					format("寻找到#R%s#交给雪人。", 取装备详细说明(任务数据[任务id].物品))
				}
