						玩家数据[任务数据[n].玩家id].角色:取消任务(任务数据[n].刷出强盗)
					end

					地图处理类:删除单位(任务数据[n].地图编号, 任务数据[n].单位编号)

					任务数据[n] = nil
				elseif 任务数据[n].类型 == 7756 then
					if 玩家数据[任务数据[n].玩家id] ~= nil then
						玩家数据[任务数据[n].玩家id].角色:取消任务(n)
						发送数据(玩家数据[任务数据[n].玩家id].连接id, 39)
