				elseif 任务数据[n].类型 == 210 or 任务数据[n].类型 == 209 or 任务数据[n].类型 == 207 or 任务数据[n].类型 == 101 or 任务数据[n].类型 == 205 or 任务数据[n].类型 == 104 or 任务数据[n].类型 == 11 or 任务数据[n].类型 == 12 or 任务数据[n].类型 == 206 or 任务数据[n].类型 == 191 or 任务数据[n].类型 == 192 or 任务数据[n].类型 == 193 or 任务数据[n].类型 == 194 or 任务数据[n].类型 == 195 or 任务数据[n].类型 == 1951 or 任务数据[n].类型 == 1952 or 任务数据[n].类型 == 1953 or 任务数据[n].类型 == 1954 or 任务数据[n].类型 == 1955 or 任务数据[n].类型 == 1956  or 任务数据[n].类型 == 1957 or 任务数据[n].类型 == 1958 or 任务数据[n].类型 == 1959 or 任务数据[n].类型 == 1960 or 任务数据[n].类型 == 1961 or 任务数据[n].类型 == 1962 or 任务数据[n].类型 == 1963 or 任务数据[n].类型 == 1964 or 任务数据[n].类型 == 1965 or 任务数据[n].类型 == 1966  or 任务数据[n].类型 == 1967 or 任务数据[n].类型 == 1968 or 任务数据[n].类型 == 1969 or 任务数据[n].类型 == 1970 or 任务数据[n].类型 == 1971 or 任务数据[n].类型 == 1972 or 任务数据[n].类型 == 1973 or 任务数据[n].类型 == 1974 or 任务数据[n].类型 == 196 or 任务数据[n].类型 == 197  or 任务数据[n].类型 == 350 or 任务数据[n].类型 == 351 or 任务数据[n].类型 == 352 or 任务数据[n].类型 == 353 or 任务数据[n].类型 == 354 or 任务数据[n].类型 == 355 or 任务数据[n].类型 == 356 or 任务数据[n].类型 == 357 or 任务数据[n].类型 == 358 then
