function 任务处理类:刷新封妖任务()
	local 临时数量 = 取随机数(10, 16)
	local 地图范围 = {
		1193,
		1110,
		1173,
		1092,
		1091,
		1174,
		1210
	}
	local 地图 = 地图范围[ygsj(#地图范围)]
	local 封妖等级 = {
		[1193.0] = 55,
		[1173.0] = 55,
		[1092.0] = 55,
		[1091.0] = 55,
		[1174.0] = 55,
		[1210.0] = 55,
		[1110.0] = 55
	}
	local dtmc = ""

	for i = 1, #地图范围 do
		for n = 1, 临时数量 do
			local 任务id = "_101_" .. os.time() .. "_" .. 随机序列 .. "_" .. 取随机数(88, 99999999)
			随机序列 = 随机序列 + 1
			local 模型 = "黑山老妖"
			local xy = 地图处理类.地图坐标[地图]:取随机点()

			if ygsj() <= 50 then
				模型 = "地狱战神"
			end

			结束时间 = 1800
			任务数据[任务id] = {
				名称 = "远古魔王",
				类型 = 101,
				id = 任务id,
				起始 = os.time(),
				结束 = 结束时间,
				玩家id = id,
				队伍组 = {},
				模型 = 模型,
				等级 = 封妖等级[地图范围[i]],
				x = xy.x,
				y = xy.y,
				地图编号 = 地图范围[i],
				地图名称 = 取地图名称(地图范围[i])
			}

			地图处理类:添加单位(任务id)
		end

		if i == 1 then
			dtmc = 取地图名称(地图范围[i])
		else
			dtmc = dtmc .. "、" .. 取地图名称(地图范围[i])
		end
	end

	广播消息({
		频道 = "xt",
		内容 = format("#P(天降横祸)#W一群妖怪家的房子被突如其来的天外陨石撞塌，现在无家可归的妖怪们正在#Y/%s#w/寻衅闹事，各路英雄赶快前往平乱啊！#35", dtmc)
	})
end

