	local 临时数量 = 取随机数(10, 16)

	玩家数据[id].角色:添加储备(临时数量 * 10000, "挖宝放妖")
	常规提示(id, "#Y/你不慎挖塌了妖怪家的房子，却意外的发现了#R/" .. 数字转简(临时数量 * 10000) .. "#Y/点储备金")

