		1110,
		1173,
		1092,
		1091,
		1174,
		1210,
		1506,
		1514,
		1876
	}
	local 地图 = 地图范围[ygsj(#地图范围)]
	local 封妖等级 = 30

	for n = 1, 临时数量 do
		local 任务id = id .. "_101_" .. os.time() .. "_" .. 随机序列 .. "_" .. 取随机数(88, 99999999)
		随机序列 = 随机序列 + 1
		local 模型 = "黑山老妖"
		local xy = 地图处理类.地图坐标[地图]:取随机点()

		if ygsj() <= 50 then
			模型 = "地狱战神"
