function 任务处理类:开启迷宫()
	for n = 1, 20 do
		for i, v in pairs(地图处理类.地图单位[1600 + n]) do
			地图处理类:删除单位(1600 + n, i)
		end
	end

	for n = 1, 20 do
		local 结束时间 = 99999
		local 真假 = {}

		if ygsj() <= 50 then
			真假 = {
				[1.0] = true,
				[2.0] = false
			}
		else
			真假 = {
				[1.0] = false,
				[2.0] = true
			}
		end

		for i = 1, 2 do
			local 任务id = i .. "_" .. n .. "_" .. 取随机数(1999, 11111) .. "_201_" .. os.time() .. "_" .. 随机序列 .. "_" .. 取随机数(88, 99999999) .. "_" .. 1600 + n .. "_" .. i
			随机序列 = 随机序列 + 1
			local 地图 = 1600 + n
			local xy = 地图处理类.地图坐标[地图]:取随机点()

			if 地图 == 1601 then
				if i == 1 then
					任务数据[任务id] = {
						名称 = "迷宫土地",
						真假 = true,
						结束 = 999999,
						类型 = 201,
						模型 = "男人_土地",
						称谓 = "迷宫传送员",
						id = 任务id,
						起始 = os.time(),
						玩家id = id,
						队伍组 = {},
						x = xy.x,
						y = xy.y,
						地图编号 = 地图,
						序列 = n,
						地图名称 = 取地图名称(地图),
						真假 = true
					}

					地图处理类:添加单位(任务id)
				end
			elseif 地图 == 1620 then
				if i == 1 then
					任务数据[任务id] = {
						名称 = "迷宫守卫",
						类型 = 201,
						结束 = 999999,
						模型 = "护卫",
						称谓 = "迷宫奖励专员",
						id = 任务id,
						起始 = os.time(),
						玩家id = id,
						队伍组 = {},
						x = xy.x,
						y = xy.y,
						地图编号 = 地图,
						序列 = n,
						地图名称 = 取地图名称(地图)
					}

					地图处理类:添加单位(任务id)
				else
					任务数据[任务id] = {
						名称 = "迷宫土地",
						真假 = false,
						结束 = 999999,
						类型 = 201,
						模型 = "男人_土地",
						称谓 = "迷宫传送员",
						id = 任务id,
						起始 = os.time(),
						玩家id = id,
						队伍组 = {},
						x = xy.x,
						y = xy.y,
						地图编号 = 地图,
						序列 = n,
						地图名称 = 取地图名称(地图),
						真假 = false
					}

					地图处理类:添加单位(任务id)
				end
			else
				任务数据[任务id] = {
					名称 = "迷宫土地",
					结束 = 999999,
					类型 = 201,
					模型 = "男人_土地",
					称谓 = "迷宫传送员",
					id = 任务id,
					起始 = os.time(),
					玩家id = id,
					队伍组 = {},
					x = xy.x,
					y = xy.y,
					地图编号 = 地图,
					序列 = n,
					真假 = 真假[i],
					地图名称 = 取地图名称(地图)
				}

				地图处理类:添加单位(任务id)

				if i == 2 and ygsj() <= 20 then
					任务id = i .. "_" .. n .. "_" .. 取随机数(1999, 11111) .. "_201_" .. os.time() .. "_" .. 随机序列 .. "_" .. 取随机数(88, 99999999) .. "_" .. 1600 + n .. "_" .. 3
					随机序列 = 随机序列 + 1
					xy = 地图处理类.地图坐标[地图]:取随机点()
					任务数据[任务id] = {
						名称 = "迷宫土地",
						结束 = 999999,
						类型 = 201,
						模型 = "男人_土地",
						称谓 = "迷宫随机传送",
						id = 任务id,
						起始 = os.time(),
						玩家id = id,
						队伍组 = {},
						x = xy.x,
						y = xy.y,
						地图编号 = 地图,
						序列 = n,
						真假 = 真假[i],
						地图名称 = 取地图名称(地图)
					}

					地图处理类:添加单位(任务id)
				end
			end
		end
	end

