function 任务处理类:开启地煞星任务(id)
	local 地图范围 = {
		1193,
		1514,
		1091,
		1140,
		1146,
		1513
	}
	local 地图范围2 = {
		1130,--1201,---
		1203,
		1131,
		1192,--1512,----
		1258,
		2001
	}
	local 地图范围3 = {
		1207,
		--1112,
		1232,
		1233,
		1203,
		2007,
		1221,
		1920
	}
	local 地煞显示地图 = {}
	local 地煞名称 = ""

	for i = 1, 30 do
		地煞名称 = Q_地煞星等级[qz((i - 1) / 2) + 1]

		for n = 1, 20 do
			local 地煞等级 = n * 10
			local 地图 = 0

			if 地煞等级 <= 60 then
				地图 = 地图范围[取随机数(1, #地图范围)]
			elseif 地煞等级 <= 120 then
				地图 = 地图范围2[取随机数(1, #地图范围2)]
			else
				地图 = 地图范围3[取随机数(1, #地图范围3)]
			end

			local xy = 地图处理类.地图坐标[地图]:取随机点()
			local 任务id = "_" .. 地煞等级 .. "_" .. 取随机数(1999, 11111) .. "304" .. os.time() .. "_" .. 随机序列 .. "_" .. 取随机数(88, 99999999) .. "_" .. 地煞等级
			随机序列 = 随机序列 + 1
			local 造型 = Q_随机模型[取随机数(1, #Q_随机模型)]
			local 武器造型 = 取高级地煞星武器造型(造型)
			任务数据[任务id] = {
				行走开关 = true,
				结束 = 1800,
				类型 = 304,
				id = 任务id,
				起始 = os.time(),
				玩家id = id,
				队伍组 = {},
				名称 = 地煞名称,
				模型 = 造型,
				武器 = 武器造型.武器,
				武器等级 = 武器造型.级别,
				等级 = 地煞等级,
				x = xy.x,
				y = xy.y,
				地图编号 = 地图,
				地图名称 = 取地图名称(地图)
			}

			if 任务数据[任务id].名称 == "初出茅庐地煞星" then
				任务数据[任务id].称谓 = "★"
			elseif 任务数据[任务id].名称 == "小有所成地煞星" then
				任务数据[任务id].称谓 = "★★"
			elseif 任务数据[任务id].名称 == "伏虎斩妖地煞星" then
				任务数据[任务id].称谓 = "★★★"
			elseif 任务数据[任务id].名称 == "御风神行地煞星" then
				任务数据[任务id].称谓 = "★★★★"
			elseif 任务数据[任务id].名称 == "履水吐焰地煞星" then
				任务数据[任务id].称谓 = "★★★★★"
				elseif 任务数据[任务id].名称 == "牛逼轰轰地煞星" then
				任务数据[任务id].称谓 = "★★★★★★"
				elseif 任务数据[任务id].名称 == "东倒西歪地煞星" then
				任务数据[任务id].称谓 = "★★★★★★★"
				elseif 任务数据[任务id].名称 == "稀奇古怪地煞星" then
				任务数据[任务id].称谓 = "★★★★★★★★"
				elseif 任务数据[任务id].名称 == "无可匹敌地煞星" then
				任务数据[任务id].称谓 = "★★★★★★★★★"
				elseif 任务数据[任务id].名称 == "十全十美地煞星" then
				任务数据[任务id].称谓 = "★★★★★★★★★★"
					elseif 任务数据[任务id].名称 == "十一星地煞星" then
				任务数据[任务id].称谓 = "★十一星★"
					elseif 任务数据[任务id].名称 == "十二星地煞星" then
				任务数据[任务id].称谓 = "★十二星★"
					elseif 任务数据[任务id].名称 == "十三星地煞星" then
				任务数据[任务id].称谓 = "★十三星★"
					elseif 任务数据[任务id].名称 == "十四星地煞星" then
				任务数据[任务id].称谓 = "★十四星★"
					elseif 任务数据[任务id].名称 == "十五星地煞星" then
				任务数据[任务id].称谓 = "★十五星★"

			end

			地图处理类:添加单位(任务id)

			地煞显示地图[#地煞显示地图 + 1] = 任务数据[任务id].地图名称
		end
	end

	删除重复(地煞显示地图)

	local 地煞显示地图1 = ""

	for i = 1, #地煞显示地图 do
		if i == 1 then
			地煞显示地图1 = 地煞显示地图[i]
		else
			地煞显示地图1 = 地煞显示地图1 .. "、" .. 地煞显示地图[i]
		end
	end

	广播消息({
		频道 = "xt",
		内容 = format("#G据可靠消息，强大而神秘的地煞星带着天界宝物已经出现在#Y%s#G场景内。只有智勇双全的强者才有机缘获得宝物，少侠敢来挑战么？" .. "#" .. 取随机数(1, 110), 地煞显示地图1)
	})
end

