function 任务处理类:开启镖王活动()
	删除指定任务类型单位(207)

	for n = 1, 6 do
		local 任务id = n .. "_" .. 取随机数(999, 1111) .. "_207_" .. os.time() .. "_" .. 随机序列 .. "_" .. 取随机数(88, 99999999)
		随机序列 = 随机序列 + 1
		local 地图 = 镖王数据[n].地图
		local 结束时间 = 99999
		任务数据[任务id] = {
			名称 = "镖师",
			类型 = 207,
			模型 = "护卫",
			称谓 = "镖王活动",
			id = 任务id,
			起始 = os.time(),
			结束 = 结束时间,
			玩家id = id,
			队伍组 = {},
			x = 镖王数据[n].x,
			y = 镖王数据[n].y,
			方向 = 镖王数据[n].z,
			地图编号 = 地图,
			序列 = n,
			地图名称 = 取地图名称(地图)
		}

		地图处理类:添加单位(任务id)
	end

	广播消息({
		频道 = "xt",
		内容 = "#G/镖王活动已经开启，各位玩家可以前往长风镖局的#R/郑镖头#G/处报名参加#32"
	})

	镖王活动 = {
		开关 = true
	}
end

