		end

		local 数量 = 取随机数(20, 40)
		local 地图 = 地图范围[n]

		for i = 1, 数量 do
			local 任务id = n .. "_" .. i .. "_" .. 取随机数(11, 88) .. "_105_" .. os.time() .. "_" .. 随机序列 .. "_" .. 取随机数(88, 99999999)
			随机序列 = 随机序列 + 1
			local 名称 = "妖魔"
			local 模型 = {
				"吸血鬼",
				"幽灵",
				"鬼将"
			}

			if ygsj() <= 50 then
				名称 = "鬼怪"
				模型 = {
					"僵尸",
					"野鬼"
				}
			end

			local xy = 地图处理类.地图坐标[地图]:取随机点()
			任务数据[任务id] = {
				行走开关 = true,
				类型 = 105,
				id = 任务id,
				起始 = os.time(),
				结束 = 结束时间,
				玩家id = id,
				队伍组 = {},
				名称 = 名称,
				模型 = 模型[取随机数(1, #模型)],
				x = xy.x,
				y = xy.y,
				地图编号 = 地图,
				地图名称 = 取地图名称(地图)
