			地图处理类:添加单位(任务id)
		end
	end

	广播消息({
		频道 = "xt",
		内容 = format("#R一群#Y妖魔鬼怪#R冲破了仙界封印，来到了#G/%s#R/作恶，还请各位英雄侠士赶紧去降服它们。", 提示名称)
	})
end

