function 任务处理类:添加一倍经验(id)
	if 单机设置 then
		local rwid = 玩家数据[id].角色:取任务(2)

		if rwid == 0 then
			self:添加双倍(1, 1, id)
		else
			任务数据[rwid].结束 = 任务数据[rwid].结束 + 经验丹时间
		end

		rwid = 玩家数据[id].角色:取任务(3)

		if rwid == 0 then
			self:添加精修时间(1, 1, id)
		else
			任务数据[rwid].结束 = 任务数据[rwid].结束 + 经验丹时间
		end
	end

	rwid = 玩家数据[id].角色:取任务(7756)

	if rwid ~= 0 then
		任务数据[rwid].结束 = 任务数据[rwid].结束 + 经验丹时间
	else
		local 任务id = id .. "_7756_" .. os.time()
		local 结束时间 = 经验丹时间
		任务数据[任务id] = {
			类型 = 7756,
			id = 任务id,
			起始 = os.time(),
			结束 = 结束时间,
			玩家id = id,
			队伍组 = {}
		}

		玩家数据[id].角色:添加任务(任务id)
		发送数据(玩家数据[id].连接id, 39)
	end
end


