function 任务处理类:设置打造160级装备任务(id, 临时类型, 级别, 序列, 属性, 制造者, 熟练度)
	local 任务id = id .. "_5_" .. os.time()
	local 结束时间 = 1e+17
	local 数量 = 1

	if 级别 <= 20 then
		数量 = 1
	elseif 级别 <= 30 then
		数量 = 2
	elseif 级别 <= 40 then
		数量 = 3
	elseif 级别 <= 50 then
		数量 = 5
	elseif 级别 <= 60 then
		数量 = 7
	elseif 级别 <= 70 then
		数量 = 9
	elseif 级别 <= 80 then
		数量 = 12
	elseif 级别 <= 90 then
		数量 = 16
	elseif 级别 <= 100 then
		数量 = 20
	elseif 级别 <= 110 then
		数量 = 24
	elseif 级别 == 160 then
		数量 = 50
	else
		数量 = 30
	end

	local 类型 = "装备"

	if 级别 == 160 then
		类型 = "160装备"
	end

	任务数据[任务id] = {
		类型 = 5,
		id = 任务id,
		起始 = os.time(),
		结束 = 结束时间,
		玩家id = id,
		队伍组 = {},
		名称 = 临时类型,
		级别 = 级别,
		序列 = 序列,
		元身属性 = 属性,
		石头 = 取强化石(),
		数量 = 数量,
		制造者 = 制造者,
		熟练度 = 熟练度,
		打造类型 = 类型
	}

	玩家数据[id].角色:添加任务(任务id)
	发送数据(玩家数据[id].连接id, 39)
	常规提示(id, "#Y/你获得了打造任务")
	发送数据(玩家数据[id].连接id, 1501, {
		名称 = 玩家数据[id].最后对话.名称,
		模型 = 玩家数据[id].最后对话.模型,
		对话 = format("你的#R/%s#W/已经在制作中了，但还欠缺%s块%s，你赶紧去寻找吧。找到后回来交给我就可以完成了。", 临时类型, 数量, 任务数据[任务id].石头)
	})
end

