function 任务处理类:设置天庭叛逆(id)
	local 地图范围 = {
		1040,
		1173,
		1092,
		1091,
		1174,
		1210,
		1110
	}
	local x待发送数据 = {}

	for i = 1, #地图范围 do
		local 临时数量 = 取随机数(10, 20)
		local 地图 = 地图范围[i]
		x待发送数据[地图] = {}

		for n = 1, 临时数量 do
			local 任务id = 地图 .. "_128_" .. os.time() .. "_" .. 随机序列 .. "_" .. 取随机数(88, 99999999) .. "_" .. n
			随机序列 = 随机序列 + 1
			local xy = 地图处理类.地图坐标[地图]:取随机点()
			local 模型范围 = {
				"持国巡守",
				"毗舍童子",
				"灵灯侍者",
				"般若天女",
				"真陀护法",
				"增长巡守",
				"金身罗汉",
				"曼珠沙华",
				"红萼仙子",
				"琴仙",
				"金铙僧",
				"灵鹤",
				"雾中仙",
				"大力金刚",
				"净瓶女娲",
				"律法女娲",
				"灵符女娲",
				"如意仙子",
				"巡游天神",
				"星灵仙子",
				"雨师",
				"天兵",
				"风伯"
			}
			local 模型 = 模型范围[取随机数(1, #模型范围)]
			local x称谓 = "天庭叛逆"
			任务数据[任务id] = {
				玩家id = 0,
				行走开关 = true,
				结束 = 1200,
				显示饰品 = true,
				事件 = "明雷活动",
				类型 = 128,
				id = 任务id,
				起始 = os.time(),
				队伍组 = {},
				名称 = 模型,
				模型 = 模型,
				等级 = 取随机数(1, 140),
				称谓 = x称谓,
				x = xy.x,
				y = xy.y,
				地图编号 = 地图,
				地图名称 = 取地图名称(地图)
			}

			table.insert(x待发送数据[地图], 地图处理类:批量添加单位(任务id))
		end
	end

	广播消息({
		频道 = "xt",
		内容 = format("#W/叛逆肆虐，一群可怕的天庭叛逆跑到了#Y/西梁女国、大唐境外、傲来国、长寿郊外、北俱芦洲、麒麟山、大唐国境#w各路英雄快去消灭它们吧#46")
	})

	for i = 1, #地图范围 do
		local 地图编号 = 地图范围[i]

		for n, v in pairs(地图处理类.地图玩家[地图编号]) do
			if 地图处理类:取同一地图(地图编号, id, n, 1) then
				发送数据(玩家数据[n].连接id, 1021, x待发送数据[地图编号])
			end
		end
	end

	x待发送数据 = nil
end

function 任务处理类:捣乱的水果(id)
	local 地图范围 = DeepCopy(刷怪地图范围.捣乱的水果)
	local 捣乱的水果等级 = {
		[1110.0] = 55,
		[1173.0] = 65,
		[1210.0] = 105,
		[1091.0] = 85,
		[1174.0] = 95,
		[1514.0] = 75,
		[1193.0] = 45,
		[1506.0] = 35
	}
	local x待发送数据 = {}

	for i = 1, #地图范围 do
		local 临时数量 = 取随机数(16, 30)
		local 地图 = 地图范围[i]
		x待发送数据[地图] = {}

		for n = 1, 临时数量 do
			local 任务id = 地图 .. "_129_" .. os.time() .. "_" .. 随机序列 .. "_" .. 取随机数(88, 99999999) .. "_" .. n
			随机序列 = 随机序列 + 1
			local xy = 地图处理类.地图坐标[地图]:取随机点()
			local 模型范围 = {
				"泡泡",
				"超级泡泡",
				"超级泡泡"
			}
			local 模型名称范围 = {
				"腐烂的水果",
				"发霉的水果",
				"未熟的水果",
				"金黄的水果",
				"苦涩的水果",
				"成熟的水果",
				"青涩的水果",
				"火红的水果",
				"金色的水果",
				"美味的水果",
				"可口的水果"
			}

			if 捣乱的水果等级[地图] >= 95 then
				模型范围 = {
					"超级泡泡"
				}
				模型名称范围 = {
					"火红的水果",
					"金色的水果",
					"美味的水果",
					"可口的水果"
				}
			elseif 捣乱的水果等级[地图] >= 65 then
				模型范围 = {
