					"超级泡泡"
				}
				模型名称范围 = {
					"金黄的水果",
					"苦涩的水果",
					"成熟的水果",
					"青涩的水果"
				}
			else
				模型范围 = {
					"泡泡"
				}
				模型名称范围 = {
					"腐烂的水果",
					"发霉的水果",
					"未熟的水果"
				}
			end

			local 名称模型 = 模型名称范围[取随机数(1, #模型名称范围)]
			local 模型 = 模型范围[取随机数(1, #模型范围)]
			local x称谓 = "调皮的水果"
			任务数据[任务id] = {
				玩家id = 0,
				行走开关 = true,
				结束 = 1200,
				显示饰品 = true,
				事件 = "明雷活动",
				类型 = 129,
				id = 任务id,
				起始 = os.time(),
				队伍组 = {},
				名称 = 名称模型,
				模型 = 模型,
				等级 = 捣乱的水果等级[地图],
				称谓 = x称谓,
				x = xy.x,
				y = xy.y,
				地图编号 = 地图,
				地图名称 = 取地图名称(地图)
			}

			table.insert(x待发送数据[地图], 地图处理类:批量添加单位(任务id))
		end
	end

	广播消息({
		频道 = "xt",
		内容 = format("#W/水果肆虐，一群可怕的捣乱的水果跑到了#Y/东海湾、江南野外、大唐国境、大唐境外、长寿郊外、花果山、北俱芦洲、麒麟山#w各路英雄快去消灭它们吧#46")
	})

	for i = 1, #地图范围 do
		local 地图编号 = 地图范围[i]

		for n, v in pairs(地图处理类.地图玩家[地图编号]) do
			if 地图处理类:取同一地图(地图编号, id, n, 1) then
				发送数据(玩家数据[n].连接id, 1021, x待发送数据[地图编号])
			end
		end
	end

	x待发送数据 = {}
end




function 任务处理类:小鬼子(id)
	local 地图范围 = DeepCopy(刷怪地图范围.小鬼子)
	local 小鬼子等级 = {
		[1110.0] = 55,
		[1173.0] = 65,
		[1210.0] = 105,
		[1091.0] = 85,
		[1174.0] = 95,
		[1514.0] = 75,
		[1193.0] = 45,
		[1506.0] = 35
	}
	local x待发送数据 = {}

	for i = 1, #地图范围 do
		local 临时数量 = 取随机数(16, 30)
		local 地图 = 地图范围[i]
		x待发送数据[地图] = {}

		for n = 1, 临时数量 do
			local 任务id = 地图 .. "_129_" .. os.time() .. "_" .. 随机序列 .. "_" .. 取随机数(88, 99999999) .. "_" .. n
