function 任务处理类:完成福利宝箱(任务id, id组)
	if 任务数据[任务id] == nil then
		return
	end

	for n = 1, #id组 do
		local id = id组[n]

		if 队伍处理类:取是否助战(玩家数据[id].队伍, n) == 0 then
			if 掉率模式 == 1 then
				取福利宝箱奖励(id, true)
			else
				if 添加活动次数(id, "福利宝箱") == false then
					return
				end

				取福利宝箱奖励(id, true)
			end
		end
	end

	地图处理类:删除单位(任务数据[任务id].地图编号, 任务数据[任务id].单位编号)

	任务数据[任务id] = nil
end

