function 任务处理类:完成齐天巨灵神(任务id, id组)
	if 任务数据[任务id] == nil then
		return
	end

	local 经验 = 0
	local 银子 = 0

	for n = 1, #id组 do
		local id = id组[n]

		if 队伍处理类:取是否助战(玩家数据[id].队伍, n) == 0 then
			local 平均等级 = 取队伍平均等级(玩家数据[id].队伍, id)
			经验 = 平均等级 * 平均等级 * 15
			银子 = 平均等级 * 400

			玩家数据[id].角色:添加经验(经验, "齐天大圣", 1)
			玩家数据[id].角色:添加银子(银子, "齐天大圣", 1)
