			召唤兽添加经验(math.floor(经验 * 0.8), id, "齐天大圣")

			local 奖励参数 = ygsj()

			if 奖励参数 <= 10 then
				if ygsj() <= 50 then
					奖励名称[id] = 快捷给道具(id, "制造指南书", 取随机数(6, 10))
