function 任务处理类:捣乱的年兽()
	年兽数据 = {
		捣乱的年兽 = 20,
		年兽王 = 4
	}
	local 地图范围 = {
		1501,
		1070,
		1208,
		1092
	}

	for n = 1, #地图范围 do
		for i = 1, 20 do
			local xy = 地图处理类.地图坐标[地图范围[n]]:取随机点()
			local 任务id = "_356_" .. os.time() .. "_" .. 取随机数(88, 99999999) .. i
			local 造型 = {
				"古代瑞兽"
			}
			local 造型 = 造型[取随机数(1, #造型)]
			任务数据[任务id] = {
				行走开关 = true,
				等级 = 100,
				结束 = 1800,
				显示饰品 = true,
				名称 = "捣乱的年兽",
				类型 = 356,
				id = 任务id,
				起始 = os.time(),
				玩家id = id,
				队伍组 = {},
				模型 = 造型,
				x = xy.x,
				y = xy.y,
				地图编号 = 地图范围[n],
				地图名称 = 取地图名称(地图范围[n])
			}

			地图处理类:添加单位(任务id)
		end
	end

	for n = 1, #地图范围 do
		local xy = 地图处理类.地图坐标[地图范围[n]]:取随机点()
		local 任务id = "_357_" .. os.time() .. "_" .. 取随机数(88, 99999999) .. n
		local 造型 = {
			"进阶古代瑞兽"
		}
		local 造型 = 造型[取随机数(1, #造型)]
		任务数据[任务id] = {
			行走开关 = true,
			等级 = 100,
			结束 = 1800,
			显示饰品 = true,
			名称 = "年兽王",
			类型 = 357,
			id = 任务id,
			起始 = os.time(),
			玩家id = id,
			队伍组 = {},
			模型 = 造型,
			x = xy.x,
			y = xy.y,
			地图编号 = 地图范围[n],
			地图名称 = 取地图名称(地图范围[n])
		}

		地图处理类:添加单位(任务id)
	end

	广播消息({
		频道 = "xt",
		内容 = format("#G在民间四处作乱的年兽出现在建邺城、长寿村、朱紫国、傲来国等地，玩家可以前去驱赶捣乱的年兽获得丰厚的奖励。" .. "#" .. 取随机数(24, 24))
	})
end

