function 任务处理类:完成捣乱的年兽(任务id, id组)
	if 任务数据[任务id] == nil then
		return
	end

	local 删 = false

	for n = 1, #id组 do
		local id = id组[n]

		if 添加活动次数(id, "捣乱的年兽") == true then
			删 = true

			通用给奖励(id, {
				活跃度 = 2,
				经验 = {
					2200,
					2500
				},
				银子 = {
					1500,
					1800
				}
			}, "捣乱的年兽", nil, "不判断次数")
		end
	end

	if 删 then
		年兽数据.捣乱的年兽 = 年兽数据.捣乱的年兽 - 1

		if 年兽数据.捣乱的年兽 <= 0 then
			年兽数据.捣乱的年兽 = 0
		end

		if 年兽数据.捣乱的年兽 == 0 and 年兽数据.年兽王 == 0 then
			任务处理类:邪恶年兽()
		end

		地图处理类:删除单位(任务数据[任务id].地图编号, 任务数据[任务id].单位编号)

		任务数据[任务id] = nil
	end
end

